 /* 4.14 searching */
 const LIN='class F { public static int cmp = 0; public static int find(int[] a, int t) { for (int i = 0; i < a.length; i++) { cmp++; if (a[i] == t) { return i; } } return -1; } }';
 const BIN='class F { public static int cmp = 0; public static int bs(int[] a, int t) { int lo = 0; int hi = a.length - 1; while (lo <= hi) { cmp++; int mid = (lo + hi) / 2; if (a[mid] == t) { return mid; } else if (a[mid] < t) { lo = mid + 1; } else { hi = mid - 1; } } return -1; } }';
 const binPic=(t)=>board('Binary search (cmp counts the passes)',['lo = 0; hi = a.length - 1','while (lo <= hi): cmp++; mid = (lo + hi) / 2','a[mid] == target: return mid','a[mid] < target: lo = mid + 1','otherwise: hi = mid - 1',t]);
 const linPic=()=>board('Linear search (cmp counts the comparisons)',['for each index i from 0 to a.length - 1:','  cmp++','  if a[i] equals the target: return i','after the loop: return -1']);
 const SORTED='int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};';
 put('srch',`Code: ${LIN} int[] a = {4, 8, 15, 16, 23, 42}; F.find(a, 15); System.out.println(F.cmp); What is printed?`,3,linPic(),'The target 15 is at index 2, so three elements are compared.');
 put('srch',`Code: ${LIN} int[] a = {4, 8, 15, 16, 23, 42}; F.find(a, 5); System.out.println(F.cmp); What is printed?`,6,linPic(),'The target is not in the array, so every element is compared before -1 is returned.');
 {const c=choose('4 -1',['5 -1','4 0'],choice++);put('srch',`Code: ${LIN} int[] a = {4, 8, 15, 16, 23, 42}; System.out.println(F.find(a, 23) + " " + F.find(a, 7)); What is printed? ${c.text}. Answer A, B or C.`,c.letter,linPic(),'23 is at index 4, and 7 is missing, so find returns -1.');}
 put('srch',`Code: ${BIN} ${SORTED} F.bs(a, 23); System.out.println(F.cmp); What is printed?`,3,binPic('target 23: mids are 4, 7, 5'),'The middles are index 4 (16), index 7 (56) and index 5 (23): three passes.');
 put('srch',`Code: ${BIN} ${SORTED} F.bs(a, 91); System.out.println(F.cmp); What is printed?`,4,binPic('target 91: mids are 4, 7, 8, 9'),'The middles are indexes 4, 7, 8 and 9: four passes.');
 put('srch',`Code: ${BIN} ${SORTED} F.bs(a, 50); System.out.println(F.cmp); What is printed?`,4,binPic('target 50 is not there'),'The middles are indexes 4, 7, 5 and 6; then lo passes hi and the loop ends after four passes.');
 {const c=choose('-1',['3','4'],choice++);put('srch',`Code: ${BIN} int[] a = {9, 2, 7, 4, 1}; System.out.println(F.bs(a, 4)); What is printed? ${c.text}. Answer A, B or C.`,c.letter,binPic('this array is not sorted'),'The array is not sorted, so the halving discards the half that holds the 4 and returns -1.');}
 put('srch','Code: class F { public static int cmp = 0; public static int bs(int[] a, int t) { int lo = 0; int hi = a.length - 1; while (lo <= hi) { cmp++; int mid = (lo + hi) / 2; if (a[mid] == t) { return mid; } else if (a[mid] < t) { lo = mid + 1; } else { hi = mid - 1; } } return -1; } } int[] a = new int[100]; for (int i = 0; i < 100; i++) { a[i] = i * 2; } int worst = 0; for (int t = -1; t <= 200; t++) { F.cmp = 0; F.bs(a, t); if (F.cmp > worst) { worst = F.cmp; } } System.out.println(worst); What is printed?',7,binPic('over every possible target in 100 values'),'Each pass halves the range, and 100 values need at most 7 passes because 2^7 = 128 is the first power of two above 100.');
 MCQ('srch',[
 ['Which condition must be true before a binary search can give a correct result?','the data must be in sorted order',['the data must contain no duplicate values','the data must be stored in an ArrayList'],'Binary search discards half the range by comparing with the middle, which only works on sorted data.'],
 ['Which data calls for a linear search, or at least cannot use a binary search?','values that are not in any particular order',['values stored in sorted order','a very long list that is already sorted'],'A linear search works in any order; a binary search needs sorted data.'],
 ['If the size of a sorted array doubles, how does the maximum number of binary search passes change?','it grows by about one pass',['it doubles','it stays the same'],'One extra pass halves the larger range back to the old size, so doubling the data adds about one pass.']]);
