 put('srch',`Code: ${LIN} int[] a = {5, 3, 5, 3}; System.out.println(F.find(a, 3)); What is printed?`,1,linPic(),'The search returns the first index where the target appears.');
 /* 4.15 sorting */
 const SEL='class S { public static int swaps = 0; public static int cmp = 0; public static void sel(int[] a, int passes) { for (int i = 0; i < passes; i++) { int m = i; for (int j = i + 1; j < a.length; j++) { cmp++; if (a[j] < a[m]) { m = j; } } int t = a[i]; a[i] = a[m]; a[m] = t; swaps++; } } }';
 const SEL2='class S { public static int swaps = 0; public static void sel(int[] a) { for (int i = 0; i < a.length - 1; i++) { int m = i; for (int j = i + 1; j < a.length; j++) { if (a[j] < a[m]) { m = j; } } if (m != i) { int t = a[i]; a[i] = a[m]; a[m] = t; swaps++; } } } }';
 const INS='class S { public static int shifts = 0; public static void ins(int[] a, int upTo) { for (int i = 1; i <= upTo; i++) { int v = a[i]; int j = i - 1; while (j >= 0 && a[j] > v) { a[j + 1] = a[j]; j--; shifts++; } a[j + 1] = v; } } }';
 const selPic=board('Selection sort, one pass per position',['for i from 0 up to passes - 1:','  m = i; scan j = i + 1 ... end; cmp++ each time','  if a[j] < a[m]: m = j','  swap a[i] and a[m]; swaps++']);
 const selPic2=board('Selection sort that swaps only when needed',['for i from 0 up to a.length - 2:','  m = index of the smallest in i ... end','  if m != i: swap a[i] and a[m]; swaps++']);
 const insPic=board('Insertion sort, rows 0 to upTo',['for i from 1 up to upTo:','  v = a[i]; j = i - 1','  while j >= 0 and a[j] > v: a[j + 1] = a[j]; j--; shifts++','  a[j + 1] = v']);
 {const c=choose('1 2 8 6',['1 2 6 8','2 6 8 1'],choice++);put('sort',`Code: ${SEL} int[] a = {6, 2, 8, 1}; S.sel(a, 1); System.out.println(a[0] + " " + a[1] + " " + a[2] + " " + a[3]); What is printed? ${c.text}. Answer A, B or C.`,c.letter,selPic,'One pass swaps the smallest value, 1, into index 0, and the 6 goes to where the 1 was.');}
 put('sort',`Code: ${SEL} int[] a = {1, 2, 3, 4, 5}; S.sel(a, a.length - 1); System.out.println(S.swaps); What is printed?`,4,selPic,'This version swaps in every pass, even when the smallest value is already in place: 4 passes, 4 swaps.');
 put('sort',`Code: ${SEL} int[] a = {9, 4, 6, 1, 8, 2}; S.sel(a, a.length - 1); System.out.println(S.cmp); What is printed?`,15,selPic,'The passes make 5, 4, 3, 2 and 1 comparisons, 15 in all, whatever the order.');
 put('sort',`Code: ${INS} int[] a = {6, 3, 5, 2}; S.ins(a, 3); System.out.println(S.shifts); What is printed?`,5,insPic,'The 3 needs 1 shift, the 5 needs 1 and the 2 needs 3: 5 shifts.');
 put('sort',`Code: ${INS} int[] a = {1, 2, 3, 4}; S.ins(a, 3); System.out.println(S.shifts); What is printed?`,0,insPic,'No value is greater than the one being inserted, so nothing shifts.');
 put('sort',`Code: ${INS} int[] a = {4, 3, 2, 1}; S.ins(a, 3); System.out.println(S.shifts); What is printed?`,6,insPic,'Each insertion shifts every earlier value: 1 + 2 + 3 = 6.');
 {const c=choose('4 7 9 2',['4 9 7 2','2 4 7 9'],choice++);put('sort',`Code: ${INS} int[] a = {9, 4, 7, 2}; S.ins(a, 2); System.out.println(a[0] + " " + a[1] + " " + a[2] + " " + a[3]); What is printed? ${c.text}. Answer A, B or C.`,c.letter,insPic,'Only rows 0 to 2 are insertion sorted, so the last value, 2, has not moved yet.');}
 put('sort',`Code: ${SEL2} int[] a = {5, 4, 3, 2, 1}; S.sel(a); System.out.println(S.swaps); What is printed?`,2,selPic2,'The first pass swaps 5 and 1 and the second swaps 4 and 2; after that every value is already in place.');
 MCQ('sort',[
 ['After three passes of selection sort on a long array, which statement is true?','the three smallest values are in positions 0, 1 and 2, in their final places',['the first three values are sorted but may still move later','the whole array is sorted'],'Each selection pass places the next smallest value for good.'],
 ['Which statement about insertion sort is true?','it does very little work when the array is already nearly sorted',['it always makes exactly as many comparisons as selection sort','it requires the data to be sorted before it starts'],'When few values are out of place, each insertion shifts few elements.'],
 ['Selection sort makes the same number of comparisons whatever the starting order. Why?','every pass scans the whole unsorted part to find its smallest value',['it stops as soon as it sees a pair in order','it only compares neighbouring pairs']," The scan has no early exit, so the comparison count depends only on the length.".trim()]]);
 mcc('sort','boolean x = "pear".compareTo("apple") > 0; boolean y = "fig".compareTo("pear") < 0; System.out.println(x && y);',PR,'true',['false',CT],'compareTo is positive when the first String comes later in alphabetical order, and negative when it comes earlier.');
 /* 4.16 and 4.17 recursion, recursive searching and sorting */
 const FACT='class R { public static int fact(int n) { if (n <= 1) { return 1; } return n * fact(n - 1); } }';
 const factPic=board('A recursive factorial',['fact(n) returns 1 when n <= 1','otherwise it returns n * fact(n - 1)']);
 put('rec',`Code: ${FACT} System.out.println(R.fact(5)); What is printed?`,120,factPic,'fact(5) is 5 * 4 * 3 * 2 * 1.');
 put('rec',`Code: ${FACT} R.fact(4); How many calls to fact are made in total, counting the first call?`,4,factPic,'fact(4) calls fact(3), which calls fact(2), which calls fact(1), which is the base case: four calls.');
 mcc('rec','class R { public static int down(int n) { return down(n - 1) + 1; } } System.out.println(R.down(3));',HAP,'StackOverflowError',['prints 3',CT],'There is no base case, so the calls never stop and the call stack overflows.');
 mcc('rec','class R { public static String up(int n) { if (n == 0) { return ""; } return up(n - 1) + n; } public static String dn(int n) { if (n == 0) { return ""; } return n + dn(n - 1); } } System.out.println(R.up(4) + " " + R.dn(4));',PR,'1234 4321',['4321 1234','1234 1234'],'up puts the current number after the smaller result, so it counts up; dn puts it before, so it counts down.');
 num('rec','class R { public static int fib(int n) { if (n <= 2) { return 1; } return fib(n - 1) + fib(n - 2); } } System.out.println(R.fib(7));',PR,13,'The sequence 1, 1, 2, 3, 5, 8, 13 has 13 as its seventh term.');
 num('rec','class R { public static int fib(int n) { if (n <= 2) { return 1; } return fib(n - 1) + fib(n - 2); } } R.fib(5);','How many calls to fib are made in total, counting the first call?',9,'fib(5) makes 9 calls: 1 + 5 for fib(4) + 3 for fib(3).');
 num('rec','class R { public static int sd(int n) { if (n < 10) { return n; } return n % 10 + sd(n / 10); } } System.out.println(R.sd(472));',PR,13,'472 gives 2 + sd(47) = 2 + 7 + sd(4) = 2 + 7 + 4 = 13.');
 num('rec','class R { public static int pw(int b, int e) { if (e == 0) { return 1; } return b * pw(b, e - 1); } } System.out.println(R.pw(2, 5));',PR,32,'2 * 2 * 2 * 2 * 2 * 1 = 32.');
