 MCQ('rec',[
 ['What is the base case of a recursive method?','the condition under which the method returns without calling itself',['the first call made from another method','the line that calls the method with a smaller value'],'The base case ends the recursion; without it the calls would never stop.'],
 ['Each call of a recursive method has its own parameters and local variables. Where does Java keep them while the calls wait?','on the call stack',['in the instance variables of the class','in a static variable shared by all the calls'],'Each call adds a frame to the call stack, and frames come off as the calls return.']]);
 const RBS='class B { public static int bs(int[] a, int t, int lo, int hi) { if (lo > hi) { return -1; } int mid = (lo + hi) / 2; if (a[mid] == t) { return mid; } if (a[mid] < t) { return bs(a, t, mid + 1, hi); } return bs(a, t, lo, mid - 1); } }';
 const rbsPic=board('Recursive binary search',['lo > hi: return -1 (not found)','a[mid] == t: return mid','a[mid] < t: search mid + 1 ... hi','otherwise: search lo ... mid - 1']);
 put('rec',`Code: ${RBS} int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91}; B.bs(a, 23, 0, 9); How many calls to bs are made in total, counting the first call?`,3,rbsPic,'The ranges are 0-9, 5-9 and 5-6; the third call finds 23 at index 5.');
 put('rec',`Code: ${RBS} int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91}; B.bs(a, 50, 0, 9); How many calls to bs are made in total, counting the first call?`,5,rbsPic,'The ranges are 0-9, 5-9, 5-6, 6-6 and finally 7-6, where lo is greater than hi.');
 MCQ('rec',[['In a recursive binary search, which two situations stop the recursion?','the target is found at the middle, or the range is empty (low is greater than high)',['the array has been completely sorted, or the target is negative','the loop counter reaches the array length, or the middle is zero'],'Those are the two base cases: found, or nothing left to search.']]);
 const MS='class M { public static int[] ms(int[] a) { if (a.length <= 1) { return a; } int h = a.length / 2; int[] l = new int[h]; int[] r = new int[a.length - h]; for (int i = 0; i < h; i++) { l[i] = a[i]; } for (int i = h; i < a.length; i++) { r[i - h] = a[i]; } return mg(ms(l), ms(r)); } public static int[] mg(int[] x, int[] y) { int[] z = new int[x.length + y.length]; int i = 0; int j = 0; int k = 0; while (i < x.length && j < y.length) { if (x[i] <= y[j]) { z[k] = x[i]; i++; } else { z[k] = y[j]; j++; } k++; } while (i < x.length) { z[k] = x[i]; i++; k++; } while (j < y.length) { z[k] = y[j]; j++; k++; } return z; } }';
 const msPic=board('Merge sort: ms splits, mg merges',['ms: an array of 0 or 1 elements is returned as is','otherwise split into a left half and a right half','sort each half with a recursive call to ms','mg merges the two sorted halves into one array']);
 put('rec',`Code: ${MS} int[] a = {5, 2, 8, 1, 9, 3, 7, 4}; M.ms(a); How many calls to ms are made in total, counting the first call?`,15,msPic,'Eight elements make 1 + 2 + 4 + 8 = 15 calls: a call for every piece down to single elements.');
 put('rec',`Code: ${MS} int[] a = {6, 1, 5, 2, 4, 3}; M.ms(a); How many calls to ms are made in total, counting the first call?`,11,msPic,'Six elements split into 3 and 3; each 3 makes 5 calls, so 1 + 5 + 5 = 11.');
